import React, { useRef, useState, useCallback, useEffect, useMemo } from 'react';
import { Canvas, useThree, ThreeEvent } from '@react-three/fiber';
import { OrbitControls, Text, PerspectiveCamera } from '@react-three/drei';
import * as THREE from 'three';
import { usePlannerStore, LayoutItem } from '../store/plannerStore';

// ── Scale factor: cm → Three.js units ────────────────────────────────
const S = 0.01; // 1 cm = 0.01 units (so 100cm = 1 unit)

// ── Container wireframe ──────────────────────────────────────────────

function ContainerBox({ length, width, height }: { length: number; width: number; height: number }) {
  const l = length * S;
  const w = width * S;
  const h = height * S;

  const positions = useMemo(() => new Float32Array([
    // Bottom
    0, 0, 0, l, 0, 0,
    l, 0, 0, l, 0, w,
    l, 0, w, 0, 0, w,
    0, 0, w, 0, 0, 0,
    // Top
    0, h, 0, l, h, 0,
    l, h, 0, l, h, w,
    l, h, w, 0, h, w,
    0, h, w, 0, h, 0,
    // Verticals
    0, 0, 0, 0, h, 0,
    l, 0, 0, l, h, 0,
    l, 0, w, l, h, w,
    0, 0, w, 0, h, w,
  ]), [l, w, h]);

  return (
    <group>
      {/* Semi-transparent fill */}
      <mesh position={[l / 2, h / 2, w / 2]}>
        <boxGeometry args={[l, h, w]} />
        <meshPhongMaterial
          color="#1a2332"
          transparent
          opacity={0.08}
          side={THREE.BackSide}
        />
      </mesh>

      {/* Floor grid */}
      <gridHelper
        args={[Math.max(l, w) * 1.5, 20, '#334155', '#1e293b']}
        position={[l / 2, 0, w / 2]}
      />

      {/* Edges */}
      <lineSegments>
        <bufferGeometry>
          <bufferAttribute
            attach="attributes-position"
            count={positions.length / 3}
            array={positions}
            itemSize={3}
          />
        </bufferGeometry>
        <lineBasicMaterial color="#64748b" linewidth={1} />
      </lineSegments>

      {/* Floor plane */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[l / 2, 0.001, w / 2]}>
        <planeGeometry args={[l, w]} />
        <meshPhongMaterial color="#1e293b" transparent opacity={0.5} />
      </mesh>
    </group>
  );
}

// ── Product Box with labels on 4 sides + dark bottom ─────────────────

interface ProductBoxProps {
  item: LayoutItem;
  isSelected: boolean;
  isHovered: boolean;
  onSelect: (item: LayoutItem) => void;
  onHover: (item: LayoutItem | null) => void;
  onContextMenu: (e: ThreeEvent<MouseEvent>, item: LayoutItem) => void;
}

function ProductBox({ item, isSelected, isHovered, onSelect, onHover, onContextMenu }: ProductBoxProps) {
  const meshRef = useRef<THREE.Group>(null);

  const l = item.length_cm * S;
  const w = item.width_cm * S;
  const h = item.height_cm * S;

  const x = item.pos_x * S;
  const y = item.pos_y * S;
  const z = item.pos_z * S;

  const baseColor = item.color_hex || '#f59e0b';
  const darkColor = darkenColor(baseColor, 0.4);

  const displayColor = isSelected ? '#22c55e' : isHovered ? '#fbbf24' : baseColor;
  const opacity = isSelected ? 0.85 : isHovered ? 0.8 : 0.75;
  const emissive = isSelected ? '#16a34a' : isHovered ? '#92400e' : '#000000';

  // Truncate long names for display
  const label = item.product_name.length > 12
    ? item.product_name.substring(0, 11) + '…'
    : item.product_name;

  const fontSize = Math.min(l, w, h) * 0.3;
  const clampedFontSize = Math.max(0.02, Math.min(fontSize, 0.08));

  return (
    <group
      ref={meshRef}
      position={[x + l / 2, y + h / 2, z + w / 2]}
    >
      {/* Main box - top & 4 sides */}
      <mesh
        onClick={(e) => { e.stopPropagation(); onSelect(item); }}
        onPointerEnter={() => onHover(item)}
        onPointerLeave={() => onHover(null)}
        onContextMenu={(e) => { e.stopPropagation(); onContextMenu(e, item); }}
      >
        <boxGeometry args={[l, h, w]} />
        <meshPhongMaterial
          color={displayColor}
          transparent
          opacity={opacity}
          emissive={emissive}
        />
      </mesh>

      {/* Dark bottom face */}
      <mesh position={[0, -h / 2 + 0.001, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[l, w]} />
        <meshPhongMaterial color={darkColor} />
      </mesh>

      {/* Dark bottom strip on each side (to indicate bottom) */}
      {/* Front side bottom strip */}
      <mesh position={[0, -h / 2 + h * 0.08, w / 2 + 0.001]}>
        <planeGeometry args={[l, h * 0.16]} />
        <meshPhongMaterial color={darkColor} transparent opacity={0.7} />
      </mesh>
      {/* Back side bottom strip */}
      <mesh position={[0, -h / 2 + h * 0.08, -w / 2 - 0.001]} rotation={[0, Math.PI, 0]}>
        <planeGeometry args={[l, h * 0.16]} />
        <meshPhongMaterial color={darkColor} transparent opacity={0.7} />
      </mesh>
      {/* Left side bottom strip */}
      <mesh position={[-l / 2 - 0.001, -h / 2 + h * 0.08, 0]} rotation={[0, -Math.PI / 2, 0]}>
        <planeGeometry args={[w, h * 0.16]} />
        <meshPhongMaterial color={darkColor} transparent opacity={0.7} />
      </mesh>
      {/* Right side bottom strip */}
      <mesh position={[l / 2 + 0.001, -h / 2 + h * 0.08, 0]} rotation={[0, Math.PI / 2, 0]}>
        <planeGeometry args={[w, h * 0.16]} />
        <meshPhongMaterial color={darkColor} transparent opacity={0.7} />
      </mesh>

      {/* Labels on 4 sides */}
      {/* Front */}
      <Text
        position={[0, 0, w / 2 + 0.003]}
        fontSize={clampedFontSize}
        color="#ffffff"
        anchorX="center"
        anchorY="middle"
        outlineWidth={0.002}
        outlineColor="#000000"
      >
        {label}
      </Text>
      {/* Back */}
      <Text
        position={[0, 0, -w / 2 - 0.003]}
        fontSize={clampedFontSize}
        color="#ffffff"
        anchorX="center"
        anchorY="middle"
        rotation={[0, Math.PI, 0]}
        outlineWidth={0.002}
        outlineColor="#000000"
      >
        {label}
      </Text>
      {/* Left */}
      <Text
        position={[-l / 2 - 0.003, 0, 0]}
        fontSize={clampedFontSize}
        color="#ffffff"
        anchorX="center"
        anchorY="middle"
        rotation={[0, -Math.PI / 2, 0]}
        outlineWidth={0.002}
        outlineColor="#000000"
      >
        {label}
      </Text>
      {/* Right */}
      <Text
        position={[l / 2 + 0.003, 0, 0]}
        fontSize={clampedFontSize}
        color="#ffffff"
        anchorX="center"
        anchorY="middle"
        rotation={[0, Math.PI / 2, 0]}
        outlineWidth={0.002}
        outlineColor="#000000"
      >
        {label}
      </Text>

      {/* Selection outline */}
      {isSelected && (
        <mesh>
          <boxGeometry args={[l + 0.01, h + 0.01, w + 0.01]} />
          <meshBasicMaterial color="#22c55e" wireframe transparent opacity={0.5} />
        </mesh>
      )}
    </group>
  );
}

// ── Drag handler scene component ─────────────────────────────────────

interface DragControllerProps {
  containerLength: number;
  containerWidth: number;
  containerHeight: number;
}

function DragController({ containerLength, containerWidth, containerHeight }: DragControllerProps) {
  const { camera, raycaster, gl } = useThree();
  const {
    layoutItems,
    selectedItemId,
    updateLayoutItem,
    pushToHistory,
  } = usePlannerStore();

  const isDraggingRef = useRef(false);
  const dragPlaneRef = useRef(new THREE.Plane(new THREE.Vector3(0, 1, 0), 0));
  const dragOffsetRef = useRef(new THREE.Vector3());
  const startPosRef = useRef({ x: 0, z: 0 });

  const handlePointerDown = useCallback((e: PointerEvent) => {
    if (e.button !== 0 || !selectedItemId) return;

    const item = layoutItems.find((i) => i.id === selectedItemId);
    if (!item) return;

    const rect = gl.domElement.getBoundingClientRect();
    const mouse = new THREE.Vector2(
      ((e.clientX - rect.left) / rect.width) * 2 - 1,
      -((e.clientY - rect.top) / rect.height) * 2 + 1
    );

    raycaster.setFromCamera(mouse, camera);

    const itemY = item.pos_y * S + (item.height_cm * S) / 2;
    dragPlaneRef.current.set(new THREE.Vector3(0, 1, 0), -itemY);

    const intersection = new THREE.Vector3();
    raycaster.ray.intersectPlane(dragPlaneRef.current, intersection);

    if (intersection) {
      dragOffsetRef.current.set(
        intersection.x - (item.pos_x * S + (item.length_cm * S) / 2),
        0,
        intersection.z - (item.pos_z * S + (item.width_cm * S) / 2)
      );
      startPosRef.current = { x: item.pos_x, z: item.pos_z };
      isDraggingRef.current = true;
    }
  }, [selectedItemId, layoutItems, camera, raycaster, gl]);

  const handlePointerMove = useCallback((e: PointerEvent) => {
    if (!isDraggingRef.current || !selectedItemId) return;

    const item = layoutItems.find((i) => i.id === selectedItemId);
    if (!item) return;

    const rect = gl.domElement.getBoundingClientRect();
    const mouse = new THREE.Vector2(
      ((e.clientX - rect.left) / rect.width) * 2 - 1,
      -((e.clientY - rect.top) / rect.height) * 2 + 1
    );

    raycaster.setFromCamera(mouse, camera);

    const intersection = new THREE.Vector3();
    raycaster.ray.intersectPlane(dragPlaneRef.current, intersection);

    if (intersection) {
      let newX = Math.round(((intersection.x - dragOffsetRef.current.x) / S - item.length_cm / 2));
      let newZ = Math.round(((intersection.z - dragOffsetRef.current.z) / S - item.width_cm / 2));

      // Clamp to container bounds
      newX = Math.max(0, Math.min(newX, containerLength - item.length_cm));
      newZ = Math.max(0, Math.min(newZ, containerWidth - item.width_cm));

      updateLayoutItem(selectedItemId, { pos_x: newX, pos_z: newZ });
    }
  }, [selectedItemId, layoutItems, camera, raycaster, gl, updateLayoutItem, containerLength, containerWidth]);

  const handlePointerUp = useCallback(() => {
    if (isDraggingRef.current) {
      isDraggingRef.current = false;
      pushToHistory();
    }
  }, [pushToHistory]);

  useEffect(() => {
    const dom = gl.domElement;
    dom.addEventListener('pointerdown', handlePointerDown);
    dom.addEventListener('pointermove', handlePointerMove);
    dom.addEventListener('pointerup', handlePointerUp);
    return () => {
      dom.removeEventListener('pointerdown', handlePointerDown);
      dom.removeEventListener('pointermove', handlePointerMove);
      dom.removeEventListener('pointerup', handlePointerUp);
    };
  }, [gl, handlePointerDown, handlePointerMove, handlePointerUp]);

  return null;
}

// ── Main Component ───────────────────────────────────────────────────

export function ContainerViewer3D() {
  const {
    projectConfig,
    layoutItems,
    selectedItemId,
    setSelectedItemId,
    contextMenu,
    showContextMenu,
    hideContextMenu,
    rotateItem,
    removeLayoutItem,
    updateLayoutItem,
    pushToHistory,
  } = usePlannerStore();

  const [hoveredItem, setHoveredItem] = useState<LayoutItem | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const moveStep = 5; // cm per key press

  const container = projectConfig?.containerType;

  // Handle right-click on product in 3D
  const handleContextMenu = useCallback((e: ThreeEvent<MouseEvent>, item: LayoutItem) => {
    e.nativeEvent.preventDefault();
    e.nativeEvent.stopPropagation();

    // Get position relative to container div
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      showContextMenu(
        e.nativeEvent.clientX - rect.left,
        e.nativeEvent.clientY - rect.top,
        item.id
      );
    }
  }, [showContextMenu]);

  // Keyboard controls
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!selectedItemId) return;

      const item = layoutItems.find((i) => i.id === selectedItemId);
      if (!item || !container) return;

      switch (e.key) {
        case 'ArrowUp':
          e.preventDefault();
          updateLayoutItem(selectedItemId, {
            pos_z: Math.max(0, item.pos_z - moveStep),
          });
          break;
        case 'ArrowDown':
          e.preventDefault();
          updateLayoutItem(selectedItemId, {
            pos_z: Math.min(container.width_cm - item.width_cm, item.pos_z + moveStep),
          });
          break;
        case 'ArrowLeft':
          e.preventDefault();
          updateLayoutItem(selectedItemId, {
            pos_x: Math.max(0, item.pos_x - moveStep),
          });
          break;
        case 'ArrowRight':
          e.preventDefault();
          updateLayoutItem(selectedItemId, {
            pos_x: Math.min(container.length_cm - item.length_cm, item.pos_x + moveStep),
          });
          break;
        case 'PageUp':
          e.preventDefault();
          updateLayoutItem(selectedItemId, {
            pos_y: Math.min(container.height_cm - item.height_cm, item.pos_y + moveStep),
          });
          break;
        case 'PageDown':
          e.preventDefault();
          updateLayoutItem(selectedItemId, {
            pos_y: Math.max(0, item.pos_y - moveStep),
          });
          break;
        case 'Delete':
          e.preventDefault();
          removeLayoutItem(selectedItemId);
          pushToHistory();
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedItemId, layoutItems, container, updateLayoutItem, removeLayoutItem, pushToHistory]);

  // Prevent default context menu
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const prevent = (e: MouseEvent) => e.preventDefault();
    el.addEventListener('contextmenu', prevent);
    return () => el.removeEventListener('contextmenu', prevent);
  }, []);

  if (!container) {
    return (
      <div className="w-full h-full flex items-center justify-center bg-gray-900">
        <p className="text-gray-400">Select or create a project to begin</p>
      </div>
    );
  }

  const camDist = Math.max(container.length_cm, container.width_cm, container.height_cm) * S * 1.5;

  return (
    <div className="relative w-full h-full" ref={containerRef}>
      <Canvas
        style={{ width: '100%', height: '100%' }}
        onPointerMissed={() => { setSelectedItemId(null); hideContextMenu(); }}
      >
        <PerspectiveCamera
          makeDefault
          position={[camDist, camDist * 0.8, camDist]}
          fov={50}
        />
        <color attach="background" args={['#0f172a']} />

        {/* Lighting */}
        <ambientLight intensity={0.4} />
        <directionalLight position={[10, 10, 5]} intensity={0.7} castShadow />
        <directionalLight position={[-5, 8, -5]} intensity={0.3} />
        <pointLight position={[0, 10, 0]} intensity={0.2} />

        {/* Container wireframe */}
        <ContainerBox
          length={container.length_cm}
          width={container.width_cm}
          height={container.height_cm}
        />

        {/* Products */}
        {layoutItems.map((item) => (
          <ProductBox
            key={item.id}
            item={item}
            isSelected={selectedItemId === item.id}
            isHovered={hoveredItem?.id === item.id}
            onSelect={(it) => { setSelectedItemId(it.id); hideContextMenu(); }}
            onHover={setHoveredItem}
            onContextMenu={handleContextMenu}
          />
        ))}

        {/* Drag controller */}
        <DragController
          containerLength={container.length_cm}
          containerWidth={container.width_cm}
          containerHeight={container.height_cm}
        />

        {/* Orbit controls */}
        <OrbitControls
          enablePan={true}
          enableZoom={true}
          enableRotate={true}
          maxPolarAngle={Math.PI / 2 - 0.05}
        />
      </Canvas>

      {/* Right-click context menu - rotation icons */}
      {contextMenu && (
        <div
          className="absolute z-50"
          style={{ left: contextMenu.x, top: contextMenu.y }}
        >
          <div className="bg-gray-900/95 backdrop-blur-xl border border-gray-600/50 rounded-xl p-2 shadow-2xl shadow-black/50 min-w-[160px]">
            <div className="text-xs text-gray-400 px-2 py-1 mb-1 font-medium">Rotate</div>
            <button
              onClick={() => rotateItem(contextMenu.itemId, 'up')}
              className="w-full flex items-center gap-3 px-3 py-2 text-sm text-white hover:bg-blue-600/20 rounded-lg transition-colors"
            >
              <span className="text-lg">⬆️</span>
              <span>Rotate Up</span>
            </button>
            <button
              onClick={() => rotateItem(contextMenu.itemId, 'down')}
              className="w-full flex items-center gap-3 px-3 py-2 text-sm text-white hover:bg-blue-600/20 rounded-lg transition-colors"
            >
              <span className="text-lg">⬇️</span>
              <span>Rotate Down</span>
            </button>
            <button
              onClick={() => rotateItem(contextMenu.itemId, 'left')}
              className="w-full flex items-center gap-3 px-3 py-2 text-sm text-white hover:bg-blue-600/20 rounded-lg transition-colors"
            >
              <span className="text-lg">⬅️</span>
              <span>Rotate Left</span>
            </button>
            <button
              onClick={() => rotateItem(contextMenu.itemId, 'right')}
              className="w-full flex items-center gap-3 px-3 py-2 text-sm text-white hover:bg-blue-600/20 rounded-lg transition-colors"
            >
              <span className="text-lg">➡️</span>
              <span>Rotate Right</span>
            </button>
            <div className="border-t border-gray-700 mt-1 pt-1">
              <button
                onClick={() => {
                  removeLayoutItem(contextMenu.itemId);
                  hideContextMenu();
                  pushToHistory();
                }}
                className="w-full flex items-center gap-3 px-3 py-2 text-sm text-red-400 hover:bg-red-600/20 rounded-lg transition-colors"
              >
                <span className="text-lg">🗑️</span>
                <span>Delete</span>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Selection info bar */}
      {selectedItemId && (() => {
        const item = layoutItems.find((i) => i.id === selectedItemId);
        if (!item) return null;
        return (
          <div className="absolute bottom-4 left-4 z-10 bg-gray-900/90 backdrop-blur-xl rounded-xl px-4 py-3 border border-gray-700/50 shadow-lg text-sm">
            <div className="text-white font-medium">{item.product_name}</div>
            <div className="text-gray-400 text-xs mt-1">
              Position: ({item.pos_x}, {item.pos_y}, {item.pos_z}) cm ·
              Size: {item.length_cm}×{item.width_cm}×{item.height_cm} cm
            </div>
            <div className="text-gray-500 text-xs mt-1">
              Arrow keys: move | PgUp/PgDn: up/down | Right-click: rotate | Del: delete
            </div>
          </div>
        );
      })()}
    </div>
  );
}

// ── Helpers ──────────────────────────────────────────────────────────

function darkenColor(hex: string, factor: number): string {
  const c = parseInt(hex.replace('#', ''), 16);
  const r = Math.round(((c >> 16) & 255) * (1 - factor));
  const g = Math.round(((c >> 8) & 255) * (1 - factor));
  const b = Math.round((c & 255) * (1 - factor));
  return `#${((r << 16) | (g << 8) | b).toString(16).padStart(6, '0')}`;
}
