import { create } from 'zustand';

// ── Types ────────────────────────────────────────────────────────────

export interface Position {
  x: number;
  y: number;
  z: number;
}

export interface Rotation {
  x: number;
  y: number;
  z: number;
}

export interface ContainerType {
  id: number;
  code: string;
  name: string;
  length_cm: number;
  width_cm: number;
  height_cm: number;
  max_payload_kg: number;
  tare_weight_kg: number;
  is_system: boolean;
}

export interface Product {
  id: string;
  name: string;
  length_cm: number;
  width_cm: number;
  height_cm: number;
  weight_kg: number;
  qty: number;
  this_side_up: boolean;
  color_hex: string;
  group_id: string;
}

export interface ProductGroup {
  id: string;
  name: string;
  color_hex: string;
  is_collapsed: boolean;
  products: Product[];
}

export interface LayoutItem {
  id: string;
  product_id: string;
  product_name: string;
  instance_no: number;
  pos_x: number;
  pos_y: number;
  pos_z: number;
  rot_x: number;
  rot_y: number;
  rot_z: number;
  length_cm: number;
  width_cm: number;
  height_cm: number;
  weight_kg: number;
  color_hex: string;
  this_side_up: boolean;
}

export interface ProjectConfig {
  name: string;
  containerType: ContainerType;
}

export interface LayoutStats {
  totalWeight: number;
  usedVolume: number;
  containerVolume: number;
  volumePercent: number;
  weightPercent: number;
  itemCount: number;
}

