// ── Color palette for groups ─────────────────────────────────────────

const GROUP_COLORS = [
  '#3B82F6', '#EF4444', '#10B981', '#F59E0B', '#8B5CF6',
  '#EC4899', '#06B6D4', '#F97316', '#14B8A6', '#6366F1',
];

// ── Helper: generate unique ID ──────────────────────────────────────

let _idCounter = Date.now();
export function genId(): string {
  return (++_idCounter).toString(36);
}

// ── Store ────────────────────────────────────────────────────────────

export interface PlannerState {
  // Phase
  projectPhase: 'setup' | 'working';
  projectConfig: ProjectConfig | null;

  // Product groups (local)
  productGroups: ProductGroup[];

  // Layout items in container
  layoutItems: LayoutItem[];

  // Selection
  selectedItemId: string | null;

  // Context menu
  contextMenu: { x: number; y: number; itemId: string } | null;

  // History
  history: LayoutItem[][];
  historyIndex: number;

  // Loading
  isAutoPackLoading: boolean;

  // Actions ─ Phase
  setProjectPhase: (phase: 'setup' | 'working') => void;
  setProjectConfig: (config: ProjectConfig) => void;
  goBackToSetup: () => void;

  // Actions ─ Product groups
  addProductGroup: (name: string) => void;
  removeProductGroup: (groupId: string) => void;
  updateProductGroup: (groupId: string, updates: Partial<ProductGroup>) => void;

  // Actions ─ Products
  addProduct: (groupId: string, product: Omit<Product, 'id' | 'group_id'>) => void;
  updateProduct: (productId: string, updates: Partial<Product>) => void;
  removeProduct: (productId: string) => void;

  // Actions ─ Layout items
  insertGroupToContainer: (groupId: string) => void;
  addLayoutItem: (item: LayoutItem) => void;
  updateLayoutItem: (itemId: string, updates: Partial<LayoutItem>) => void;
  removeLayoutItem: (itemId: string) => void;
  clearLayoutItems: () => void;
  setSelectedItemId: (id: string | null) => void;

  // Actions ─ Context menu
  showContextMenu: (x: number, y: number, itemId: string) => void;
  hideContextMenu: () => void;

  // Actions ─ Rotation
  rotateItem: (itemId: string, direction: 'up' | 'down' | 'left' | 'right') => void;

  // Actions ─ History
  pushToHistory: () => void;
  undo: () => void;
  redo: () => void;

  // Actions ─ Loading
  setAutoPackLoading: (loading: boolean) => void;

  // Computed
  getLayoutStats: () => LayoutStats;
}

export const usePlannerStore = create<PlannerState>((set, get) => ({
  projectPhase: 'setup',
  projectConfig: null,
  productGroups: [],
  layoutItems: [],
  selectedItemId: null,
  contextMenu: null,
  history: [[]],
  historyIndex: 0,
  isAutoPackLoading: false,

  // ── Phase ──────────────────────────────────────────────────────────

  setProjectPhase: (phase) => set({ projectPhase: phase }),

  setProjectConfig: (config) =>
    set({
      projectConfig: config,
      projectPhase: 'working',
      layoutItems: [],
      productGroups: [],
    }),

  goBackToSetup: () =>
    set({
      projectPhase: 'setup',
      projectConfig: null,
      layoutItems: [],
      selectedItemId: null,
      contextMenu: null,
    }),

  // ── Product Groups ─────────────────────────────────────────────────

  addProductGroup: (name) =>
    set((state) => {
      const colorIdx = state.productGroups.length % GROUP_COLORS.length;
      const newGroup: ProductGroup = {
        id: genId(),
        name: name || `Group ${state.productGroups.length + 1}`,
        color_hex: GROUP_COLORS[colorIdx],
        is_collapsed: false,
        products: [],
      };
      return { productGroups: [...state.productGroups, newGroup] };
    }),

  removeProductGroup: (groupId) =>
    set((state) => ({
      productGroups: state.productGroups.filter((g) => g.id !== groupId),
    })),

  updateProductGroup: (groupId, updates) =>
    set((state) => ({
      productGroups: state.productGroups.map((g) =>
        g.id === groupId ? { ...g, ...updates } : g
      ),
    })),

  // ── Products ───────────────────────────────────────────────────────

  addProduct: (groupId, product) =>
    set((state) => {
      const newProduct: Product = {
        ...product,
        id: genId(),
        group_id: groupId,
      };
      return {
        productGroups: state.productGroups.map((g) =>
          g.id === groupId
            ? { ...g, products: [...g.products, newProduct] }
            : g
        ),
      };
    }),

  updateProduct: (productId, updates) =>
    set((state) => ({
      productGroups: state.productGroups.map((g) => ({
        ...g,
        products: g.products.map((p) =>
          p.id === productId ? { ...p, ...updates } : p
        ),
      })),
    })),

  removeProduct: (productId) =>
    set((state) => ({
      productGroups: state.productGroups.map((g) => ({
        ...g,
        products: g.products.filter((p) => p.id !== productId),
      })),
    })),

  // ── Layout Items ───────────────────────────────────────────────────

  insertGroupToContainer: (groupId) =>
    set((state) => {
      const group = state.productGroups.find((g) => g.id === groupId);
      if (!group || !state.projectConfig) return state;

      const container = state.projectConfig.containerType;
      const newItems: LayoutItem[] = [];
      let currentX = 0;
      let currentY = 0;
      let currentZ = 0;
      let rowMaxZ = 0;
      let layerMaxY = 0;

      // Simple bin-packing: place items left-to-right, front-to-back, bottom-to-top
      for (const product of group.products) {
        for (let i = 0; i < product.qty; i++) {
          const l = product.length_cm;
          const w = product.width_cm;
          const h = product.height_cm;

          // Check if fits in current row
          if (currentX + l > container.length_cm) {
            // Move to next row (along Z)
            currentX = 0;
            currentZ += rowMaxZ;
            rowMaxZ = 0;
          }

          if (currentZ + w > container.width_cm) {
            // Move to next layer (up)
            currentX = 0;
            currentZ = 0;
            currentY += layerMaxY;
            rowMaxZ = 0;
            layerMaxY = 0;
          }

          if (currentY + h > container.height_cm) {
            // Container full, stop
            break;
          }

          newItems.push({
            id: genId(),
            product_id: product.id,
            product_name: product.name,
            instance_no: i + 1,
            pos_x: currentX,
            pos_y: currentY,
            pos_z: currentZ,
            rot_x: 0,
            rot_y: 0,
            rot_z: 0,
            length_cm: l,
            width_cm: w,
            height_cm: h,
            weight_kg: product.weight_kg,
            color_hex: group.color_hex,
            this_side_up: product.this_side_up,
          });

          currentX += l;
          rowMaxZ = Math.max(rowMaxZ, w);
          layerMaxY = Math.max(layerMaxY, h);
        }
      }

      const updatedItems = [...state.layoutItems, ...newItems];

      // Push to history
      const newHistory = state.history.slice(0, state.historyIndex + 1);
      newHistory.push(JSON.parse(JSON.stringify(updatedItems)));

      return {
        layoutItems: updatedItems,
        history: newHistory,
        historyIndex: newHistory.length - 1,
      };
    }),

  addLayoutItem: (item) =>
    set((state) => ({
      layoutItems: [...state.layoutItems, item],
    })),

  updateLayoutItem: (itemId, updates) =>
    set((state) => ({
      layoutItems: state.layoutItems.map((item) =>
        item.id === itemId ? { ...item, ...updates } : item
      ),
    })),

  removeLayoutItem: (itemId) =>
    set((state) => ({
      layoutItems: state.layoutItems.filter((item) => item.id !== itemId),
      selectedItemId: state.selectedItemId === itemId ? null : state.selectedItemId,
    })),

  clearLayoutItems: () =>
    set({ layoutItems: [], selectedItemId: null, contextMenu: null }),

  setSelectedItemId: (id) => set({ selectedItemId: id, contextMenu: null }),

  // ── Context Menu ───────────────────────────────────────────────────

  showContextMenu: (x, y, itemId) =>
    set({ contextMenu: { x, y, itemId }, selectedItemId: itemId }),

  hideContextMenu: () => set({ contextMenu: null }),

  // ── Rotation ───────────────────────────────────────────────────────

  rotateItem: (itemId, direction) =>
    set((state) => {
      const item = state.layoutItems.find((i) => i.id === itemId);
      if (!item) return state;

      let updates: Partial<LayoutItem> = {};

      switch (direction) {
        case 'up':
          updates = { rot_x: (item.rot_x + 90) % 360 };
          // Swap height and width when rotating around X
          if (item.rot_x % 180 === 0) {
            updates.height_cm = item.width_cm;
            updates.width_cm = item.height_cm;
          } else {
            updates.height_cm = item.width_cm;
            updates.width_cm = item.height_cm;
          }
          break;
        case 'down':
          updates = { rot_x: (item.rot_x - 90 + 360) % 360 };
          updates.height_cm = item.width_cm;
          updates.width_cm = item.height_cm;
          break;
        case 'left':
          updates = { rot_y: (item.rot_y + 90) % 360 };
          // Swap length and width when rotating around Y
          updates.length_cm = item.width_cm;
          updates.width_cm = item.length_cm;
          break;
        case 'right':
          updates = { rot_y: (item.rot_y - 90 + 360) % 360 };
          updates.length_cm = item.width_cm;
          updates.width_cm = item.length_cm;
          break;
      }

      return {
        layoutItems: state.layoutItems.map((i) =>
          i.id === itemId ? { ...i, ...updates } : i
        ),
        contextMenu: null,
      };
    }),

  // ── History ────────────────────────────────────────────────────────

  pushToHistory: () =>
    set((state) => {
      const newHistory = state.history.slice(0, state.historyIndex + 1);
      newHistory.push(JSON.parse(JSON.stringify(state.layoutItems)));
      if (newHistory.length > 50) newHistory.shift();
      return {
        history: newHistory,
        historyIndex: newHistory.length - 1,
      };
    }),

  undo: () =>
    set((state) => {
      if (state.historyIndex > 0) {
        const newIndex = state.historyIndex - 1;
        return {
          historyIndex: newIndex,
          layoutItems: JSON.parse(JSON.stringify(state.history[newIndex])),
          selectedItemId: null,
          contextMenu: null,
        };
      }
      return state;
    }),

  redo: () =>
    set((state) => {
      if (state.historyIndex < state.history.length - 1) {
        const newIndex = state.historyIndex + 1;
        return {
          historyIndex: newIndex,
          layoutItems: JSON.parse(JSON.stringify(state.history[newIndex])),
          selectedItemId: null,
          contextMenu: null,
        };
      }
      return state;
    }),

  // ── Loading ────────────────────────────────────────────────────────

  setAutoPackLoading: (loading) => set({ isAutoPackLoading: loading }),

  // ── Computed ───────────────────────────────────────────────────────

  getLayoutStats: () => {
    const state = get();
    const container = state.projectConfig?.containerType;
    if (!container) {
      return {
        totalWeight: 0,
        usedVolume: 0,
        containerVolume: 0,
        volumePercent: 0,
        weightPercent: 0,
        itemCount: 0,
      };
    }

    const containerVolume =
      container.length_cm * container.width_cm * container.height_cm;
    const totalWeight = state.layoutItems.reduce(
      (sum, item) => sum + item.weight_kg,
      0
    );
    const usedVolume = state.layoutItems.reduce(
      (sum, item) => sum + item.length_cm * item.width_cm * item.height_cm,
      0
    );

    return {
      totalWeight: Math.round(totalWeight * 100) / 100,
      usedVolume,
      containerVolume,
      volumePercent:
        containerVolume > 0
          ? Math.round((usedVolume / containerVolume) * 10000) / 100
          : 0,
      weightPercent:
        container.max_payload_kg > 0
          ? Math.round((totalWeight / container.max_payload_kg) * 10000) / 100
          : 0,
      itemCount: state.layoutItems.length,
    };
  },
}));
