import React from 'react';
import { Package, Weight, TrendingUp, Box, Ruler } from 'lucide-react';
import { usePlannerStore } from '../store/plannerStore';

export function ContainerStatsOverlay() {
  const { projectConfig, getLayoutStats } = usePlannerStore();

  const container = projectConfig?.containerType;
  if (!container) return null;

  const stats = getLayoutStats();

  const containerVolM3 = stats.containerVolume / 1_000_000;
  const usedVolM3 = stats.usedVolume / 1_000_000;
  const freeVolM3 = containerVolM3 - usedVolM3;
  const freeWeight = container.max_payload_kg - stats.totalWeight;

  return (
    <div className="absolute top-4 right-4 z-40 w-64">
      <div className="bg-gray-900/85 backdrop-blur-xl border border-gray-700/50 rounded-xl p-4 shadow-2xl shadow-black/30">
        {/* Header */}
        <div className="flex items-center gap-2 mb-3 pb-2 border-b border-gray-700/50">
          <Box className="w-4 h-4 text-blue-400" />
          <h3 className="text-sm font-semibold text-white">{container.name}</h3>
        </div>

        {/* Dimensions */}
        <div className="flex items-center gap-1.5 mb-3 text-xs text-gray-400">
          <Ruler className="w-3 h-3" />
          <span>{container.length_cm} × {container.width_cm} × {container.height_cm} cm</span>
        </div>

        {/* Volume bar */}
        <div className="mb-3">
          <div className="flex items-center justify-between mb-1">
            <div className="flex items-center gap-1.5 text-xs text-gray-400">
              <Package className="w-3 h-3" />
              <span>Volume</span>
            </div>
            <span className="text-xs font-semibold text-green-400">
              {stats.volumePercent.toFixed(1)}%
            </span>
          </div>
          <div className="w-full bg-gray-700/50 h-2 rounded-full overflow-hidden">
            <div
              className="bg-gradient-to-r from-green-500 to-emerald-400 h-full rounded-full transition-all duration-300"
              style={{ width: `${Math.min(stats.volumePercent, 100)}%` }}
            />
          </div>
          <div className="flex justify-between mt-1 text-xs text-gray-500">
            <span>{usedVolM3.toFixed(2)} m³ used</span>
            <span>{freeVolM3.toFixed(2)} m³ free</span>
          </div>
        </div>

        {/* Weight bar */}
        <div className="mb-3">
          <div className="flex items-center justify-between mb-1">
            <div className="flex items-center gap-1.5 text-xs text-gray-400">
              <Weight className="w-3 h-3" />
              <span>Weight</span>
            </div>
            <span className={`text-xs font-semibold ${stats.weightPercent > 90 ? 'text-red-400' : 'text-orange-400'}`}>
              {stats.weightPercent.toFixed(1)}%
            </span>
          </div>
          <div className="w-full bg-gray-700/50 h-2 rounded-full overflow-hidden">
            <div
              className={`h-full rounded-full transition-all duration-300 ${
                stats.weightPercent > 90
                  ? 'bg-gradient-to-r from-red-500 to-red-400'
                  : 'bg-gradient-to-r from-orange-500 to-amber-400'
              }`}
              style={{ width: `${Math.min(stats.weightPercent, 100)}%` }}
            />
          </div>
          <div className="flex justify-between mt-1 text-xs text-gray-500">
            <span>{stats.totalWeight} kg</span>
            <span>{freeWeight > 0 ? freeWeight.toFixed(1) : 0} kg free</span>
          </div>
        </div>

        {/* Items count */}
        <div className="flex items-center justify-between pt-2 border-t border-gray-700/50">
          <div className="flex items-center gap-1.5 text-xs text-gray-400">
            <TrendingUp className="w-3 h-3" />
            <span>Items loaded</span>
          </div>
          <span className="text-sm font-bold text-blue-400">{stats.itemCount}</span>
        </div>
      </div>
    </div>
  );
}
