import React, { useState } from 'react';
import {
  ChevronDown,
  ChevronRight,
  Plus,
  Trash2,
  Send,
  Package,
  X,
} from 'lucide-react';
import { usePlannerStore, Product } from '../store/plannerStore';

export function ProductGroupManager() {
  const {
    productGroups,
    addProductGroup,
    removeProductGroup,
    updateProductGroup,
    addProduct,
    updateProduct,
    removeProduct,
    insertGroupToContainer,
    isAutoPackLoading,
  } = usePlannerStore();

  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
  const [newGroupName, setNewGroupName] = useState('');
  const [showAddGroup, setShowAddGroup] = useState(false);

  // Per-group product form state
  const [editingProductId, setEditingProductId] = useState<string | null>(null);

  const toggleGroup = (groupId: string) => {
    const next = new Set(expandedGroups);
    if (next.has(groupId)) next.delete(groupId);
    else next.add(groupId);
    setExpandedGroups(next);
  };

  const handleAddGroup = () => {
    if (!newGroupName.trim()) return;
    addProductGroup(newGroupName.trim());
    setNewGroupName('');
    setShowAddGroup(false);
  };

  const handleAddProduct = (groupId: string) => {
    addProduct(groupId, {
      name: 'New Product',
      length_cm: 50,
      width_cm: 40,
      height_cm: 30,
      weight_kg: 10,
      qty: 1,
      this_side_up: false,
      color_hex: '#F59E0B',
    });
  };

  const handleInsertGroup = (groupId: string) => {
    insertGroupToContainer(groupId);
  };

  return (
    <div className="space-y-3">
      {/* Add Group Button */}
      <div>
        {showAddGroup ? (
          <div className="flex gap-2">
            <input
              type="text"
              value={newGroupName}
              onChange={(e) => setNewGroupName(e.target.value)}
              placeholder="Group name..."
              className="flex-1 px-3 py-2 bg-gray-800/80 border border-gray-600/50 rounded-lg text-white text-sm placeholder-gray-500 focus:outline-none focus:ring-1 focus:ring-blue-500/50"
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && handleAddGroup()}
            />
            <button
              onClick={handleAddGroup}
              className="px-3 py-2 bg-green-600 hover:bg-green-500 text-white rounded-lg text-sm font-medium transition-all"
            >
              Add
            </button>
            <button
              onClick={() => { setShowAddGroup(false); setNewGroupName(''); }}
              className="px-3 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg text-sm transition-all"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        ) : (
          <button
            onClick={() => setShowAddGroup(true)}
            className="w-full px-4 py-2.5 bg-gradient-to-r from-blue-600/20 to-cyan-600/20 hover:from-blue-600/30 hover:to-cyan-600/30 border border-blue-500/30 text-blue-400 hover:text-blue-300 rounded-xl text-sm font-medium flex items-center justify-center gap-2 transition-all"
          >
            <Plus className="w-4 h-4" />
            Add Product Group
          </button>
        )}
      </div>

      {/* Empty state */}
      {productGroups.length === 0 && (
        <div className="text-center py-8">
          <Package className="w-12 h-12 mx-auto text-gray-600 mb-3" />
          <p className="text-gray-400 text-sm">No product groups yet</p>
          <p className="text-gray-500 text-xs mt-1">Add a group to start</p>
        </div>
      )}

      {/* Groups */}
      {productGroups.map((group) => {
        const isExpanded = expandedGroups.has(group.id);
        const totalQty = group.products.reduce((s, p) => s + p.qty, 0);
        const totalWeight = group.products.reduce((s, p) => s + p.weight_kg * p.qty, 0);

        return (
          <div
            key={group.id}
            className="bg-gray-800/60 backdrop-blur rounded-xl border border-gray-700/50 overflow-hidden"
          >
            {/* Group Header */}
            <div className="p-3 flex items-center gap-2">
              <button
                onClick={() => toggleGroup(group.id)}
                className="flex items-center gap-2 flex-1 text-left min-w-0"
              >
                {isExpanded ? (
                  <ChevronDown className="w-4 h-4 text-gray-400 flex-shrink-0" />
                ) : (
                  <ChevronRight className="w-4 h-4 text-gray-400 flex-shrink-0" />
                )}
                <div
                  className="w-4 h-4 rounded-sm flex-shrink-0"
                  style={{ backgroundColor: group.color_hex }}
                />
                <div className="min-w-0 flex-1">
                  <h3 className="font-semibold text-white text-sm truncate">{group.name}</h3>
                  <p className="text-xs text-gray-500">
                    {group.products.length} items · {totalQty} pcs · {totalWeight.toFixed(1)} kg
                  </p>
                </div>
              </button>

              {/* Insert to Container */}
              <button
                onClick={() => handleInsertGroup(group.id)}
                disabled={isAutoPackLoading || totalQty === 0}
                className="px-3 py-1.5 bg-gradient-to-r from-green-600 to-emerald-600 hover:from-green-500 hover:to-emerald-500 text-white rounded-lg text-xs font-medium disabled:opacity-40 flex items-center gap-1.5 transition-all shadow-sm shadow-green-600/20 flex-shrink-0"
                title="Insert all products into container"
              >
                <Send className="w-3.5 h-3.5" />
                Insert
              </button>

              {/* Delete Group */}
              <button
                onClick={() => removeProductGroup(group.id)}
                className="p-1.5 text-gray-500 hover:text-red-400 hover:bg-red-900/20 rounded-lg transition-all flex-shrink-0"
                title="Delete group"
              >
                <Trash2 className="w-3.5 h-3.5" />
              </button>
            </div>

            {/* Products */}
            {isExpanded && (
              <div className="border-t border-gray-700/50">
                {group.products.map((product) => (
                  <ProductRow
                    key={product.id}
                    product={product}
                    isEditing={editingProductId === product.id}
                    onEdit={() => setEditingProductId(
                      editingProductId === product.id ? null : product.id
                    )}
                    onUpdate={(updates) => updateProduct(product.id, updates)}
                    onDelete={() => removeProduct(product.id)}
                    groupColor={group.color_hex}
                  />
                ))}

                {/* Add Product */}
                <div className="p-2">
                  <button
                    onClick={() => handleAddProduct(group.id)}
                    className="w-full px-3 py-2 bg-gray-900/50 hover:bg-gray-900/80 border border-dashed border-gray-600/50 text-gray-400 hover:text-white rounded-lg text-xs flex items-center justify-center gap-1.5 transition-all"
                  >
                    <Plus className="w-3 h-3" />
                    Add Product
                  </button>
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ── Product Row ──────────────────────────────────────────────────────

interface ProductRowProps {
  product: Product;
  isEditing: boolean;
  onEdit: () => void;
  onUpdate: (updates: Partial<Product>) => void;
  onDelete: () => void;
  groupColor: string;
}

function ProductRow({ product, isEditing, onEdit, onUpdate, onDelete, groupColor }: ProductRowProps) {
  return (
    <div className="border-b border-gray-700/30 last:border-b-0">
      {/* Compact view */}
      <div
        className="px-3 py-2.5 hover:bg-gray-750/50 cursor-pointer transition-colors flex items-center gap-2"
        onClick={onEdit}
      >
        <div
          className="w-2.5 h-2.5 rounded-sm flex-shrink-0"
          style={{ backgroundColor: groupColor }}
        />
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between">
            <span className="text-sm text-white font-medium truncate">{product.name}</span>
            <span className="text-xs text-yellow-400 font-bold flex-shrink-0 ml-2">
              {product.qty} pcs
            </span>
          </div>
          <div className="text-xs text-gray-500 mt-0.5">
            {product.length_cm}×{product.width_cm}×{product.height_cm} cm · {product.weight_kg} kg
            {product.this_side_up && (
              <span className="ml-1.5 text-red-400">↑ Up</span>
            )}
          </div>
        </div>
      </div>

      {/* Edit form */}
      {isEditing && (
        <div className="px-3 pb-3 space-y-2 bg-gray-900/40">
          {/* Name */}
          <input
            type="text"
            value={product.name}
            onChange={(e) => onUpdate({ name: e.target.value })}
            className="w-full px-2.5 py-1.5 bg-gray-800 border border-gray-600/50 rounded-lg text-white text-sm focus:outline-none focus:ring-1 focus:ring-blue-500/50"
            placeholder="Product name"
          />

          {/* L, W, H */}
          <div className="grid grid-cols-3 gap-1.5">
            <div>
              <label className="block text-xs text-gray-500 mb-0.5">L (cm)</label>
              <input
                type="number"
                value={product.length_cm}
                onChange={(e) => onUpdate({ length_cm: Number(e.target.value) || 0 })}
                className="w-full px-2 py-1.5 bg-gray-800 border border-gray-600/50 rounded-lg text-white text-sm focus:outline-none focus:ring-1 focus:ring-blue-500/50"
                min={1}
              />
            </div>
            <div>
              <label className="block text-xs text-gray-500 mb-0.5">W (cm)</label>
              <input
                type="number"
                value={product.width_cm}
                onChange={(e) => onUpdate({ width_cm: Number(e.target.value) || 0 })}
                className="w-full px-2 py-1.5 bg-gray-800 border border-gray-600/50 rounded-lg text-white text-sm focus:outline-none focus:ring-1 focus:ring-blue-500/50"
                min={1}
              />
            </div>
            <div>
              <label className="block text-xs text-gray-500 mb-0.5">H (cm)</label>
              <input
                type="number"
                value={product.height_cm}
                onChange={(e) => onUpdate({ height_cm: Number(e.target.value) || 0 })}
                className="w-full px-2 py-1.5 bg-gray-800 border border-gray-600/50 rounded-lg text-white text-sm focus:outline-none focus:ring-1 focus:ring-blue-500/50"
                min={1}
              />
            </div>
          </div>

          {/* Weight, Qty */}
          <div className="grid grid-cols-2 gap-1.5">
            <div>
              <label className="block text-xs text-gray-500 mb-0.5">Weight (kg)</label>
              <input
                type="number"
                value={product.weight_kg}
                onChange={(e) => onUpdate({ weight_kg: Number(e.target.value) || 0 })}
                className="w-full px-2 py-1.5 bg-gray-800 border border-gray-600/50 rounded-lg text-white text-sm focus:outline-none focus:ring-1 focus:ring-blue-500/50"
                min={0}
                step={0.1}
              />
            </div>
            <div>
              <label className="block text-xs text-gray-500 mb-0.5">Total PCS</label>
              <input
                type="number"
                value={product.qty}
                onChange={(e) => onUpdate({ qty: Number(e.target.value) || 0 })}
                className="w-full px-2 py-1.5 bg-gray-800 border border-gray-600/50 rounded-lg text-white text-sm focus:outline-none focus:ring-1 focus:ring-blue-500/50"
                min={1}
              />
            </div>
          </div>

          {/* This Side Up + Actions */}
          <div className="flex items-center justify-between pt-1">
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={product.this_side_up}
                onChange={(e) => onUpdate({ this_side_up: e.target.checked })}
                className="w-4 h-4 rounded border-gray-600 bg-gray-800 text-blue-600 focus:ring-blue-500 focus:ring-offset-0"
              />
              <span className="text-xs text-gray-300">↑ This Side Up</span>
            </label>
            <button
              onClick={onDelete}
              className="px-2 py-1 text-red-400 hover:text-red-300 hover:bg-red-900/20 rounded text-xs flex items-center gap-1 transition-all"
            >
              <Trash2 className="w-3 h-3" />
              Delete
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
